<?php
session_start();require_once __DIR__.'/config.php';require_role('petugas');$pdo=db();
$headers=['KODE','NAMA ALAT','LOKASI','STATUS KALIBRASI','TANGGAL KALIBRASI','KONDISI ALAT','INTERVAL KALIBRASI (BULAN)','NOMOR SERTIFIKAT','MERK / TIPE','TAHUN PEROLEHAN','CATATAN'];
if(isset($_GET['template'])){$rows=[['OVN-01','Oven','Ruang Pengujian','Terkalibrasi',date('d/m/Y'),'Baik','12','CERT-001','Memmert UN55','2025','Contoh data. Silakan hapus baris ini.']];}else{$q=$pdo->query("SELECT kode_alat,nama_alat,lokasi,status_kalibrasi,tanggal_kalibrasi,kondisi_alat,interval_kalibrasi_bulan,nomor_sertifikat,merk_tipe,tahun_perolehan,catatan FROM alat ORDER BY kode_alat");$rows=[];foreach($q as $r)$rows[]=[$r['kode_alat'],$r['nama_alat'],$r['lokasi'],$r['status_kalibrasi'],$r['tanggal_kalibrasi']?date('d/m/Y',strtotime($r['tanggal_kalibrasi'])):'',$r['kondisi_alat'],$r['interval_kalibrasi_bulan'],$r['nomor_sertifikat'],$r['merk_tipe'],$r['tahun_perolehan'],$r['catatan']];}
function col($n){$s='';while($n){$n--; $s=chr(65+$n%26).$s;$n=intdiv($n,26);}return $s;}function cell($v,$r,$c){return '<c r="'.col($c).$r.'" t="inlineStr"><is><t xml:space="preserve">'.htmlspecialchars((string)$v,ENT_XML1).'</t></is></c>';}
$tmp=sys_get_temp_dir().'/lm_'.bin2hex(random_bytes(4));mkdir($tmp.'/xl/worksheets',0777,true);mkdir($tmp.'/xl/_rels',0777,true);mkdir($tmp.'/_rels',0777,true);$sheet='<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData>';$all=array_merge([$headers],$rows);foreach($all as $ri=>$row){$r=$ri+1;$sheet.='<row r="'.$r.'">';foreach($row as $ci=>$v)$sheet.=cell($v,$r,$ci+1);$sheet.='</row>';}$sheet.='</sheetData></worksheet>';file_put_contents($tmp.'/xl/worksheets/sheet1.xml',$sheet);file_put_contents($tmp.'/[Content_Types].xml','<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/></Types>');file_put_contents($tmp.'/_rels/.rels','<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>');file_put_contents($tmp.'/xl/workbook.xml','<?xml version="1.0" encoding="UTF-8"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="Data Alat" sheetId="1" r:id="rId1"/></sheets></workbook>');file_put_contents($tmp.'/xl/_rels/workbook.xml.rels','<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/></Relationships>');$out=$tmp.'.xlsx';$z=new ZipArchive();$z->open($out,ZipArchive::CREATE|ZipArchive::OVERWRITE);$it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($tmp,FilesystemIterator::SKIP_DOTS));foreach($it as $f)$z->addFile($f->getPathname(),substr($f->getPathname(),strlen($tmp)+1));$z->close();header('Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');header('Content-Disposition: attachment; filename="'.(isset($_GET['template'])?'template_data_alat':'data_alat_'.date('Y-m-d')).'.xlsx"');readfile($out);exit;
